BANDS = json.loads('[{"name": "early", "min": 1, "max": 7, "deadline": {"type": "business_days", "n": 12}, "attempts": [{"amount": "full_or_floor", "date": "last_business_day_of_week"}]}, {"name": "late", "min": 8, "max": 45, "deadline": {"type": "business_days", "n": 7}, "attempts": [{"amount": "full_or_floor", "date": "last_business_day_of_week"}, {"amount": "floor", "date": "deadline"}]}]')
