        late = [pf[k]['name'] + ' (use its deadline ' + d_say(datetime.date.fromisoformat(pf[k]['deadline'])) + ')' for k in ids if x > datetime.date.fromisoformat(pf[k]['deadline'])]
        if not late:
            return 'OK for every product.'
        return ('OK for: ' + ', '.join(ok) + '. ' if ok else '') + 'TOO LATE for: ' + ', '.join(late) + '.'
    while d <= end:
        if is_biz(d):
            cal.append(d_iso(d) + ' ' + d_say(d) + ': business day' + (' (today)' if d == today else '') + '. ' + verdict(d))
        else:
            nb = next_biz(d, False)
            cal.append(d_iso(d) + ' ' + d_say(d) + ': NOT a business day (' + why_not(d) + '). Next business day ' + d_say(nb) + ': ' + verdict(nb))
        d = d + datetime.timedelta(days=1)
    wk = ['"today" = ' + d_say(today), '"tomorrow" = ' + d_say(today + datetime.timedelta(days=1)), '"the day after tomorrow" = ' + d_say(today + datetime.timedelta(days=2))]
    monday = today - datetime.timedelta(days=today.weekday())
    for k in range(7):
        this_d = monday + datetime.timedelta(days=k)
        next_d = this_d + datetime.timedelta(days=7)
        wk.append('"this ' + DOW[k] + '" = ' + d_say(this_d) + (' (already past)' if this_d < today else '') + '; "next ' + DOW[k] + '" = ' + d_say(next_d))
    vars['account_facts'] = 'PRODUCTS, in this order:\n' + '\n'.join(facts)
    vars['calendar_facts'] = 'CALENDAR (look every date up here, never count days yourself):\n' + '\n'.join(cal) + '\n\nDAY WORDS (the following calendar week starts on Monday; look the date up in the CALENDAR above):\n' + '\n'.join(wk)
    vars['pfacts_json'] = json.dumps(pf)
    vars['known_pids'] = json.dumps(ids)
    vars['product_count'] = str(len(ids))
    if len(ids) == 1:
        st = STATEMENT['single'].format(line=says[0])
    else:
        st = STATEMENT['multi'].format(count=len(ids), lines=' '.join(says))
    vars['debt_statement'] = st
    vars['facts_state'] = 'ok' if ids else 'empty'
except Exception as ex:
    vars['facts_state'] = 'error'
    vars['account_facts'] = 'ERROR ' + str(ex)
    vars['calendar_facts'] = ''
    vars['debt_statement'] = ''

