PTYPES = json.loads('{"credit_card": {"spoken": "credit card ending {card_last4}", "floor_field": "minimum_payment", "floor_spoken": "minimum payment"}, "personal_loan": {"spoken": "personal loan", "floor_field": "instalment_amount", "floor_spoken": "instalment amount"}, "car_loan": {"spoken": "car loan", "floor_field": "instalment_amount", "floor_spoken": "instalment amount"} }')
CB = json.loads('{"start": "10:00", "end": "19:00", "days": ["today", "next_business_day"], "business_days_only": true}')
