        return 'Every product is handled. Now tell the customer in one or two sentences what was recorded' + (' and what could not be recorded' if L.get('gave_up') else '') + ', then call ' + 'transition_to_end_done' + '.'
    return 'Products that still have no recorded promise and no note: ' + ', '.join(p + ' (' + pf.get(p, dict()).get('name', '') + ')' for p in open_) + '. For each of them that the customer agreed to in the read-back, call create_promise. For each of them without an agreed promise, call add_note with its reason.'

GIVE_UP = 'Tell the customer the promise for this product could not be recorded because of a technical problem, then call add_note for this product with reason service_error.'

try:
    if isinstance(result, dict):
        result.pop('header', None)
    d = result.get('data') if isinstance(result, dict) else None
    pid = str(vars.get('cp_pid') or '')
    L = ledger()
    name = pfacts().get(pid, dict()).get('name', pid)
    if isinstance(d, dict) and d.get('ok') in (True, 'true', 'True') and isinstance(result, dict) and result.get('status_code') in (200, '200', None):
        if pid not in L['promises']:
            L['promises'].append(pid)
        save_ledger(L)
        rb = config_body = vars.get('cp_last') or ''
        msg = 'The promise for ' + name + ' IS recorded' + (': ' + rb if rb else '') + '. When you tell the customer, use exactly this amount and date. ' + remaining_text(L)
    else:
        n = int(L['fails'].get(pid, 0)) + 1
        L['fails'][pid] = n
        if n < 2:
            msg = 'The promise for ' + name + ' was NOT recorded: the service failed. Do NOT say it is recorded. Call create_promise again right now, once, with exactly the same values.'
        else:
            if pid not in L['gave_up']:
                L['gave_up'].append(pid)
            msg = 'The promise for ' + name + ' was NOT recorded, for the second time. Do NOT try again and do NOT say it is recorded. ' + GIVE_UP + ' ' + remaining_text(L)
        save_ledger(L)
    if isinstance(d, dict):
        d['what_to_do_next'] = msg
    elif isinstance(result, dict):
        result['data'] = {'ok': False, 'what_to_do_next': msg}
except Exception:
    pass

